import copy, os, sys
import torch, torch.distributed as dist, torch.nn.functional as F
import torch.multiprocessing as mp
from transformers import LlamaConfig, LlamaForCausalLM
sys.path.insert(0, "/app")
from pipeline_parallel import train_step_pipeline_afab

CFG = dict(vocab_size=64, hidden_size=32, intermediate_size=64, num_hidden_layers=5,
           num_attention_heads=4, num_key_value_heads=2, max_position_embeddings=64)

def make(seed=0):
    torch.manual_seed(seed)
    return LlamaForCausalLM(LlamaConfig(**CFG))

def data(nmb=3, mb=2, seq=8):
    torch.manual_seed(123)
    ins = [torch.randint(0, 64, (mb, seq)) for _ in range(nmb)]
    tgs = [torch.randint(0, 64, (mb, seq)) for _ in range(nmb)]
    return ins, tgs

def reference():
    m = make(); ins, tgs = data()
    acts, grads = {}, {}
    for i, l in enumerate(m.model.layers):
        l.register_forward_hook(lambda mod, a, o, i=i: acts.setdefault(i, []).append(
            (o[0] if isinstance(o,(tuple,list)) else o).detach().clone()))
        l.register_full_backward_hook(lambda mod, gi, go, i=i: grads.setdefault(i, []).append(go[0].detach().clone()))
    losses = []
    for x, y in zip(ins, tgs):
        out = m(input_ids=x).logits
        loss = F.cross_entropy(out.reshape(-1, out.size(-1)).float(), y.reshape(-1)) / len(ins)
        loss.backward(); losses.append(loss.item())
    return m, acts, grads, sum(losses)

def worker(rank, world_size, ref_acts, ref_grads, ref_loss, ref_grad_params, q):
    os.environ.update(MASTER_ADDR="127.0.0.1", MASTER_PORT="29517")
    dist.init_process_group("gloo", rank=rank, world_size=world_size)
    m = make(); ins, tgs = data()
    acts, grads = {}, {}
    for i, l in enumerate(m.model.layers):
        l.register_forward_hook(lambda mod, a, o, i=i: acts.setdefault(i, []).append(
            (o[0] if isinstance(o,(tuple,list)) else o).detach().clone()))
        l.register_full_backward_hook(lambda mod, gi, go, i=i: grads.setdefault(i, []).append(go[0].detach().clone()))
    loss = train_step_pipeline_afab(m, ins, tgs, torch.device("cpu"), torch.float32)
    errs = []
    ran = sorted(acts)
    if not ran: errs.append(f"rank{rank}: no layers ran")
    for i in ran:
        for a, b in zip(acts[i], ref_acts[i]):
            d = (a-b).abs().max().item()
            if d > 1e-5: errs.append(f"rank{rank} fwd layer{i} diff {d}")
        for a, b in zip(grads.get(i, []), ref_grads[i]):
            d = (a-b).abs().max().item()
            if d > 1e-5: errs.append(f"rank{rank} bwd layer{i} diff {d}")
    if rank == world_size-1 and abs(float(loss)-ref_loss) > 1e-5:
        errs.append(f"loss {float(loss)} vs {ref_loss}")
    # param grads for owned layers
    for i in ran:
        for (n, p) in m.model.layers[i].named_parameters():
            g = p.grad; rg = ref_grad_params[f"{i}.{n}"]
            if g is None: errs.append(f"rank{rank} no grad {i}.{n}"); continue
            d = (g-rg).abs().max().item()
            if d > 1e-5: errs.append(f"rank{rank} pgrad {i}.{n} diff {d}")
    q.put((rank, ran, errs))
    dist.destroy_process_group()

if __name__ == "__main__":
    refm, ra, rg, rl = reference()
    rp = {f"{i}.{n}": p.grad.clone() for i, l in enumerate(refm.model.layers) for n, p in l.named_parameters()}
    for ws in (1, 2, 3):
        q = mp.get_context("spawn").Manager().Queue()
        mp.spawn(worker, args=(ws, ra, rg, rl, rp, q), nprocs=ws, join=True)
        res = sorted([q.get() for _ in range(ws)])
        print("world_size", ws, [(r, l) for r, l, _ in res])
        bad = [e for _, _, es in res for e in es]
        print("  ERRORS:" if bad else "  OK", *bad[:8], sep="\n   " if bad else " ")
